from __future__ import absolute_import
from builtins import str

import os
import re
import sys
import json
import time
from taf.ul.trs_e2e_fw.lib.oam.admin.counters.datetime_operations import DatetimeOperations
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.exceptions import PMCountersValidationError
from datetime import datetime, timedelta
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.utils import config_utils
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


class Counters(BaseClass):
    """
    Counters
    """
    initial_values = 0

    def __init__(self):
        super(Counters, self).__init__()
        self.datetime_ops = DatetimeOperations()
        self.config = ConfigHandler.get_config()

    def _get_json_file_content(self, analysis_file):
        counters_analysis_dict = {}
        counters_analysis_files = [os.path.join(self.config['common_resources_path'],
                                                analysis_file),
                                   os.path.join(self.config['feature_resources_path'],
                                                analysis_file)]
        for counters_analysis_file in counters_analysis_files:
            if os.path.exists(counters_analysis_file):
                with open(counters_analysis_file, "r") as file_handle:
                    counters_analysis_dict.update(json.load(file_handle))
        return counters_analysis_dict

    def pm_counters_start(self, **kwargs):
        """
        Start counter

        @param kwargs:
            dut: string, to be referred from `testline_config`
            additional_wait_time: int, The profile name in counters analysis file
            pm_interval: int, he PM files generation interval in minutes
            alias: string, Name of the execution context

        @return:

        @raise:
            Exception

        """
        alias = kwargs.get("alias", 'default')
        # ocp profile has information to login to ocp from vcbts
        remote_device = [kwargs.get("dut", "vcbts"), "ocp"]
        pm_interval = kwargs.get("pm_interval", '15')
        additional_wait_time = kwargs.get('additional_wait_time', 60)
        return self._get_interval_start_end_times(remote_device, additional_wait_time, pm_interval)

    def verify_pm_counters(self, **kwargs):
        """
        Stop and verify pm counters

        @param kwargs:
            counter_analysis_file: The counters analysis file in
            fw_user_path/testcases/resources/ and fw_user_path/testcases/<feature>/resources/
            analysis: Analysis name from the counters_analysis.json
            dut: string, to be referred from`testline_config`
            additional_wait_time: int, The profile name in counters analysis file
            pm_interval: int, The PM files generation interval in minutes
            alias: string, Name of the execution context

        @return:

        @raise:
            Exception
        """
        alias = kwargs.get('alias', 'default')
        # ocp profile has information to login to ocp from vcbts
        remote_device = [kwargs.get("dut", "vcbts"), "ocp"]
        pm_interval = kwargs.get("pm_interval", '15')
        analysis = kwargs.pop("analysis")
        counter_analysis_file = kwargs.pop("counter_analysis_file")
        measurement_id = None
        additional_wait_time = kwargs.get('additional_wait_time', 60)
        counters_ref = self._get_json_file_content(counter_analysis_file)
        self.interval2_starttime, self.interval2_endtime = self._get_interval_start_end_times(
            remote_device, additional_wait_time, pm_interval)
        self._wait_for_counters_arrival_to_cu(remote_device, int(pm_interval))
        try:
            # This is just to check if the connection alive
            self.factory.cu_oam.get_active_software_version(connection=alias)
        except:
            self.setup_oamops(dut=remote_device[0], alias=alias, timeout=200)
        error_flag = True
        dimension_dist_name = list(counters_ref["counters"][analysis].keys())[0]
        for counter_id, c_value in list(counters_ref["counters"][analysis][dimension_dist_name].items()):
            final_values = self.factory.cu_oam.get_counter(
                measurement_id=measurement_id,
                dimension_dist_name=dimension_dist_name,
                counter_id=counter_id, connection=alias)
            logger.debug("Counter response is {}".format(final_values))
            if not final_values['values']:
                raise Exception("No counter value is fetched {}".format(final_values))
            logger.debug("final value: {} for counter: {}".format(final_values, counter_id))
            counter_value = final_values['values'][-1]['value']
            counter_start_time = final_values['values'][-1]['start_time']
            logger.debug("Final counter value is {} and start time is {}".format(counter_value, counter_start_time))
            counters_ref["counters"][analysis][dimension_dist_name][counter_id]["value"] = counter_value
            if counter_value is not None:
                error_flag = self._get_result(analysis, counter_id, c_value, dimension_dist_name, error_flag)
            else:
                error_flag = False
                counter_value["result"] = "Failed - Counter not found"

        json_filename = 'execution_logs/{}_{}_counters.json'.format(
            analysis, config_utils.get_config_variable(["bts_id"]))
        logger.debug("Json file name :: {}".format(str(json_filename)))
        if not os.path.exists(os.path.dirname(json_filename)):
            os.makedirs(os.path.dirname(json_filename))
        logger.debug("writing to json file... ")
        self._write_to_json_file(counters_ref["counters"][analysis], json_filename)
        if not error_flag:
            logger.debug(counters_ref["counters"][analysis])
            raise PMCountersValidationError(
                "Atleast one counter validation failed, refer to counter analysis summary file "
                "{}".format(json_filename))
        else:
            return counters_ref["counters"][analysis]

    def _get_result(self, analysis, counter, counter_value, distname, error_flag):
        if counter_value["analysis_type"].lower() == "current":
            output = int(counter_value["value"])
        lower_bound, upper_bound = self._convert_range(counter_value["expected_value"])
        lower_bound = int(int(lower_bound) - (float(counter_value["tolerance"]) / 100.0 *
                                              int(lower_bound)))
        if sys.version_info[0] >= 3:
            max_num = sys.maxsize
        else:
            max_num = sys.maxint
        if not upper_bound == max_num:
            upper_bound = int(int(upper_bound) + (float(counter_value["tolerance"]) / 100.0 *
                                                  int(upper_bound)))
        logger.debug('lower bound: {} upper bound: {}'.format(str(lower_bound), str(upper_bound)))
        logger.debug('expected val: {} output val: {}'.format(counter_value["expected_value"],
                                                              str(output)))
        if (int(lower_bound) <= output <= int(upper_bound)) or \
                counter_value["expected_value"] == counter_value["value"]:
            counter_value["result"] = "Pass"
            counter_value["output_val"] = output
            counter_value["final_counter_value"] = counter_value["value"]
        else:
            counter_value["result"] = "Failed - Evaluation Failed"
            counter_value["output_val"] = output
            counter_value["final_counter_value"] = counter_value["value"]
            error_flag = False
        return error_flag

    def _convert_range(self, range_value):
        list_split = list(re.split(r'\.\.', range_value))
        if len(list_split) == 2:
            if list_split[0].strip() == '*':
                lower_bound = -sys.maxsize - 1  # -2147483648
            else:
                lower_bound = int(list_split[0])
            if list_split[1].strip() == '*':
                upper_bound = sys.maxsize
            else:
                upper_bound = int(list_split[1])
        elif len(list_split) == 1:
            upper_bound = lower_bound = int(list_split[0])
        else:
            return 0

        return lower_bound, upper_bound

    def _write_to_json_file(self, final_value, json_filename):
        with open(json_filename, 'w') as j_file:
            json.dump(final_value, j_file)

    def get_currenttime_on_gnb(self, dut, format='%Y-%m-%d %H:%M:%S', time_zone='cu'):
        """
        Get current time on Gnb

        @param dut: string, to be referred from 'testline_config`
        @param format: string, date format
        @param time_zone: string, time zone

        @return: datetime, Current date and time on the gnb in requested format

        @raise
            Exception
        """
        logger.debug("Getting current time on gnb ...")
        remote_obj = RemoteConnection()
        remote_obj.setup_remote_access(remote_device=dut)
        if time_zone.lower() == 'utc':
            time_zone = '-u'
        else:
            time_zone = ''
        datetime_string = remote_obj.remote_command_execute(
            command="date {} '+%Y-%m-%d %H:%M:%S'".format(time_zone)).replace('\n', '')
        logger.debug("Current Time on enb is {}".format(datetime_string))
        remote_obj.teardown_remote_access()
        return datetime.strptime(datetime_string.strip(), format)

    def _wait_for_counters_arrival_to_cu(self, dut, interval):
        enb_current_time = self.get_currenttime_on_gnb(dut=dut)
        wait_mins = 0
        if enb_current_time.minute % interval == 0:
            wait_mins += interval
            logger.debug("mode is 0 Wait for {} mins".format(wait_mins))
        else:
            wait_mins = (enb_current_time.minute % interval)
            logger.debug("mode is {} Wait for {} mins".format(enb_current_time.minute % interval,
                                                              wait_mins))
        wait_seconds = (wait_mins + 1) * 60
        logger.debug('==== Waiting {} for counters arrival on CU'.format(timedelta(seconds=wait_seconds)))
        time.sleep(wait_seconds)

    def _get_interval_start_end_times(self, remote_device, additional_wait_time, pm_interval):
        enb_current_time = self.get_currenttime_on_gnb(remote_device)
        logger.debug('Current Time On eNB: {}'.format(enb_current_time))
        interval_starttime = self.datetime_ops.get_current_interval_start_time(
            current_time=enb_current_time, interval=pm_interval,
            additional_wait_time=additional_wait_time)
        self.datetime_ops.wait_for_next_interval(enb_current_time, pm_interval,
                                                 additional_wait_time=0)
        interval_endtime = self.get_currenttime_on_gnb(dut=remote_device)
        logger.debug('==== PM Interval Startime: {} Endtime: {}'.format(interval_starttime,
                                                                        interval_endtime))
        return interval_starttime, interval_endtime

    def get_counter_info(self, **kwargs):
        counter_id = kwargs['counter_id']
        measurement_id = kwargs["measurement_id"]
        connection = kwargs.get("alias", "alias")
        return self.factory.cu_oam.get_counter_info(counter_id, measurement_id, connection=connection)

    def get_measurements(self, **kwargs):
        alias = kwargs.get('alias', "default")
        return self.factory.cu_oam.get_measurements(connection=alias)

    def get_measurement_info(self, **kwargs):
        measurement_id = kwargs["measurement_id"]
        connection = kwargs.get("alias", "default")
        return self.factory.cu_oam.get_measurement_info(measurement_id, connection=connection)
